 if(message==WM_ENABLE&&!wp&&!preparationEntered){preparationEntered=true;const auto owner=GetParent(field);const auto button=saveNamed(owner,L"OK");SendMessageW(owner,WM_CLOSE,0,0);SendMessageW(owner,WM_COMMAND,MAKEWPARAM(GetDlgCtrlID(button),BN_CLICKED),(LPARAM)button);preparationRetained=IsWindow(owner)!=FALSE;}
